const Module = require("module");
const lib = require("vt2-vuln-lib");

// TOP-LEVEL (module-scope) capability escape via a COMPOSITE CALL
// ARGUMENT -- Node's own Module constructor (an authoritative loader
// capability) is wrapped in an ordinary-looking object literal and
// passed directly as an argument to a local, ordinary-looking
// configure(...) function. The final VT-307d invariant review found this
// the more fundamental gap left by VT-307c-capability-floor: that fix's
// own escape detection recognized a BARE capability argument
// (configure(Module)) but not one NESTED inside a composite value
// (configure({ loader: Module })) -- the single most idiomatic container
// expression in all of JavaScript sailed through the argument-escape
// check completely untouched, reproduced end-to-end with NO unknown API
// name involved anywhere. VT-307c-capability-flow closes this with a
// generic value-container walker that recurses through object/array
// literals, spreads, conditionals, and concise-arrow bodies looking for
// an authoritative capability nested at any depth, rather than
// enumerating one more argument shape. Before that fix this construct
// was invisible entirely (not even an unsupported_construct edge). It
// runs the moment this module is loaded, never inside any function, and
// the analyzer can never rule out that configure uses the escaped
// capability to load a different installed module, including the
// separate, never-imported top-level vt2-vuln-lib@1.9.0 instance.
function configure(loaderConfig) {
  return loaderConfig;
}
configure({ loader: Module });

function useHolder() {
  return lib.dangerousOp();
}

module.exports = { useHolder };
